using System;
using System.Data;
using System.Drawing;
using System.Threading;
using System.Windows.Forms;

using DevExpress.XtraGrid.Views.BandedGrid;

using Libs;
using Global;
using Service;
using DeclarationManager;
using SimsObject;

namespace ScheduleManager.Teaching
{
    /// <summary>
    /// Bảng tổng hợp chi tiết giờ GV: 4 cụm lưới, mỗi cụm cột khác nhau.
    /// 1) Giờ giảng dạy - SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New
    /// 2) Hoạt động khác (TeacherWorkID=35) - SIM_TeachingTimeAdded_SearchForEdit_Request_PM
    /// 3) Học tập bồi dưỡng (TeacherWorkID=34) - cùng store trên
    /// 4) NCKH - SIM_TeachingTimeResearch_Search
    /// </summary>
    public partial class frmBangTongHopGioChiTietGiangVien : FormBase, IForm
    {
        #region Consts

        public const string PERMISSION_VIEW = "frmBangTongHopGioChiTietGiangVien_View";

        public const int TEACHER_WORK_HOAT_DONG_KHAC = 35;
        public const int TEACHER_WORK_HOC_TAP_BOI_DUONG = 34;

        #endregion

        #region Variables

        private DataTable dtbTeaching = null;
        private DataTable dtbWork35 = null;
        private DataTable dtbWork34 = null;
        private DataTable dtbResearch = null;
        private bool bolIsRefresh = false;

        #endregion

        #region IForm Members

        private static frmBangTongHopGioChiTietGiangVien _instance = null;

        public static frmBangTongHopGioChiTietGiangVien Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmBangTongHopGioChiTietGiangVien();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmBangTongHopGioChiTietGiangVien()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                if (bolIsRefresh)
                {
                    uSubjectGroup.RefrehData();
                    uYearSemester.RefrehData();
                }
                else
                {
                    uSubjectGroup.InitData();
                    uYearSemester.InitData();
                }

                SIM_TeacherService.InitGridLookUpEdit(lookupTeacherID);
                bolIsRefresh = false;
            }
        }

        public void RefreshReferenceData()
        {
            uSubjectGroup.RefrehData();
            uYearSemester.RefrehData();
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                ReadData();
                EndProcess();
            }
        }

        private void ReadData()
        {
            dtbTeaching = LoadTeachingData();
            dtbWork35 = LoadTeacherWorkData(TEACHER_WORK_HOAT_DONG_KHAC);
            dtbWork34 = LoadTeacherWorkData(TEACHER_WORK_HOC_TAP_BOI_DUONG);
            dtbResearch = LoadResearchData();

            bool bolHasData =
                HasRows(dtbTeaching)
                || HasRows(dtbWork35)
                || HasRows(dtbWork34)
                || HasRows(dtbResearch);

            if (!bolHasData)
            {
                ClearAllGrids();
                MessageManager.Warning("Không có dữ liệu!");
                return;
            }

            if (HasRows(dtbTeaching))
                ApplyQuyDoiColumns(dtbTeaching);

            if (HasRows(dtbWork35))
                EnsureStandardHourColumn(dtbWork35);

            if (HasRows(dtbWork34))
                EnsureStandardHourColumn(dtbWork34);

            if (HasRows(dtbResearch))
                EnsureTeacherNameParts(dtbResearch);

            InitGridTeaching();
            InitGridTeacherWork(gvWork35, "Nhóm hoạt động khác");
            InitGridTeacherWork(gvWork34, "Nhóm học tập bồi dưỡng");
            InitGridResearch();

            gcTeaching.DataSource = dtbTeaching;
            gcWork35.DataSource = dtbWork35;
            gcWork34.DataSource = dtbWork34;
            gcResearch.DataSource = dtbResearch;

            gvTeaching.BestFitColumns();
            gvWork35.BestFitColumns();
            gvWork34.BestFitColumns();
            gvResearch.BestFitColumns();
        }

        private static bool HasRows(DataTable dtb)
        {
            return dtb != null && dtb.Rows.Count > 0;
        }

        private void ClearAllGrids()
        {
            gcTeaching.DataSource = null;
            gcWork35.DataSource = null;
            gcWork34.DataSource = null;
            gcResearch.DataSource = null;
        }

        private bool IsFullYear()
        {
            if (chkFullYear.Checked)
                return true;

            return uYearSemester.SemesterEditValue == null
                || uYearSemester.SemesterEditValue.ToString().Trim() == "";
        }

        private DataTable MergeSemesterData(DataTable dtbHK1, DataTable dtbHK2)
        {
            if (dtbHK1 == null || dtbHK1.Rows.Count == 0)
                return dtbHK2;

            if (dtbHK2 == null || dtbHK2.Rows.Count == 0)
                return dtbHK1;

            DataTable dtbResult = dtbHK1.Clone();

            foreach (DataRow row in dtbHK1.Rows)
                dtbResult.ImportRow(row);

            foreach (DataRow row in dtbHK2.Rows)
                dtbResult.ImportRow(row);

            return dtbResult;
        }

        #region Load - Giờ giảng dạy

        private DataTable LoadTeachingData()
        {
            SIM_Branch obj = new SIM_Branch();

            if (IsFullYear())
            {
                DataTable dtbHK1 = obj.GetDataTable(
                    "SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", "1",
                    "@IsContractTeaching", false
                );

                DataTable dtbHK2 = obj.GetDataTable(
                    "SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", "2",
                    "@IsContractTeaching", false
                );

                return MergeSemesterData(dtbHK1, dtbHK2);
            }

            return obj.GetDataTable(
                "SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New",
                "@ScienceID", uSubjectGroup.ScienceEditValue,
                "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                "@TeacherID", lookupTeacherID.EditValue,
                "@YearID", uYearSemester.YearIDEditValue,
                "@Semester", uYearSemester.SemesterEditValue,
                "@IsContractTeaching", false
            );
        }

        private void ApplyQuyDoiColumns(DataTable dt)
        {
            if (!dt.Columns.Contains("TongLTTH"))
                dt.Columns.Add("TongLTTH", typeof(decimal));

            if (!dt.Columns.Contains("QuyDoiGio"))
                dt.Columns.Add("QuyDoiGio", typeof(decimal));

            foreach (DataRow row in dt.Rows)
            {
                decimal lt = ToDecimal(GetColumnValue(row, "TotalQuantity_Theory"));
                decimal th = ToDecimal(GetColumnValue(row, "TotalQuantity_Practice"));
                decimal heSo = ToDecimal(GetColumnValue(row, "HeSo"));
                decimal classSize = ToDecimal(GetColumnValue(row, "ClassSize"));

                if (heSo == 0)
                    heSo = 1;

                decimal tong = lt + th;
                row["TongLTTH"] = tong;

                if (row["QuyDoiGio"] != DBNull.Value && ToDecimal(row["QuyDoiGio"]) > 0)
                    continue;

                row["QuyDoiGio"] = tong * heSo * GetHeSoSiSo(classSize);
            }
        }

        private static decimal GetHeSoSiSo(decimal classSize)
        {
            if (classSize <= 35)
                return 1.00m;

            if (classSize >= 36 && classSize <= 50)
                return 1.10m;

            if (classSize >= 51)
                return 1.20m;

            return 1.00m;
        }

        #endregion

        #region Load - Hoạt động khác / Học tập bồi dưỡng

        private DataTable LoadTeacherWorkData(int teacherWorkId)
        {
            SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();

            if (IsFullYear())
            {
                DataTable dtbHK1 = SearchTeacherWork(obj, 1, teacherWorkId);
                DataTable dtbHK2 = SearchTeacherWork(obj, 2, teacherWorkId);
                return MergeSemesterData(dtbHK1, dtbHK2);
            }

            int semester = 1;
            if (uYearSemester.SemesterEditValueInt32.HasValue)
                semester = uYearSemester.SemesterEditValueInt32.Value;

            return SearchTeacherWork(obj, semester, teacherWorkId);
        }

        private DataTable SearchTeacherWork(SIM_TeachingTimeAdded obj, int semester, int teacherWorkId)
        {
            DataTable dtb = obj.GetDataTable(
                "SIM_TeachingTimeAdded_SearchForEdit_Request_PM",
                "@ScienceID", uSubjectGroup.ScienceEditValue,
                "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                "@TeacherID", lookupTeacherID.EditValue,
                "@YearID", uYearSemester.YearIDEditValue,
                "@Semester", semester,
                "@TeacherWorkID", teacherWorkId
            );

            return dtb;
        }

        private void CalculateStandardHour(DataRow drw)
        {
            if (drw == null)
                return;

            if (drw["RequestTotal"] == DBNull.Value
                || drw["RequestTotal"].ToString().Trim() == "")
            {
                drw["StandardHour"] = DBNull.Value;
                return;
            }

            decimal requestTotal = Convert.ToDecimal(drw["RequestTotal"]);
            int teacherWorkId = Convert.ToInt32(drw["TeacherWorkID"]);
            decimal standardHour = 0;

            if (teacherWorkId == TEACHER_WORK_HOAT_DONG_KHAC)
                standardHour = requestTotal * 52m / 160m;
            else if (teacherWorkId == TEACHER_WORK_HOC_TAP_BOI_DUONG)
                standardHour = requestTotal * 26m / 80m;
            else
            {
                drw["StandardHour"] = DBNull.Value;
                return;
            }

            drw["StandardHour"] = Math.Round(standardHour, 2, MidpointRounding.AwayFromZero);
        }

        private void EnsureStandardHourColumn(DataTable dtb)
        {
            if (dtb == null)
                return;

            if (!dtb.Columns.Contains("StandardHour"))
                dtb.Columns.Add("StandardHour", typeof(decimal));

            foreach (DataRow drw in dtb.Rows)
                CalculateStandardHour(drw);
        }

        #endregion

        #region Load - NCKH

        private DataTable LoadResearchData()
        {
            SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();

            if (IsFullYear())
            {
                DataTable dtbHK1 = obj.GetDataTable(
                    "SIM_TeachingTimeResearch_Search",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", 1,
                    "@Keyword", null
                );

                DataTable dtbHK2 = obj.GetDataTable(
                    "SIM_TeachingTimeResearch_Search",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", 2,
                    "@Keyword", null
                );

                return MergeSemesterData(dtbHK1, dtbHK2);
            }

            return obj.GetDataTable(
                "SIM_TeachingTimeResearch_Search",
                "@ScienceID", uSubjectGroup.ScienceEditValue,
                "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                "@TeacherID", lookupTeacherID.EditValue,
                "@YearID", uYearSemester.YearIDEditValue,
                "@Semester", uYearSemester.SemesterEditValue,
                "@Keyword", null
            );
        }

        private void EnsureTeacherNameParts(DataTable dt)
        {
            if (dt == null)
                return;

            if (!dt.Columns.Contains("TeacherFirstName"))
                dt.Columns.Add("TeacherFirstName", typeof(string));

            if (!dt.Columns.Contains("TeacherLastName"))
                dt.Columns.Add("TeacherLastName", typeof(string));

            if (!dt.Columns.Contains("TeacherName"))
                return;

            foreach (DataRow row in dt.Rows)
            {
                string firstName = GetString(row, "TeacherFirstName");
                string lastName = GetString(row, "TeacherLastName");
                if (firstName != "" || lastName != "")
                    continue;

                string fullName = GetString(row, "TeacherName");
                if (fullName == "")
                    continue;

                int idx = fullName.LastIndexOf(' ');
                if (idx > 0)
                {
                    row["TeacherFirstName"] = fullName.Substring(0, idx).Trim();
                    row["TeacherLastName"] = fullName.Substring(idx + 1).Trim();
                }
                else
                {
                    row["TeacherLastName"] = fullName;
                }
            }
        }

        #endregion

        #region Init Grid

        private void InitAllGridsEmpty()
        {
            InitGridTeaching();
            InitGridTeacherWork(gvWork35, "Nhóm hoạt động khác");
            InitGridTeacherWork(gvWork34, "Nhóm học tập bồi dưỡng");
            InitGridResearch();
        }

        private void InitGridTeaching()
        {
            gvTeaching.Bands.Clear();
            gvTeaching.Columns.Clear();
            gvTeaching.OptionsBehavior.Editable = false;

            GridBand gbBand = CreateBand(gvTeaching, "Nhóm giờ giảng dạy");

            AddColumn(gvTeaching, gbBand, "TeacherID", "Mã GV", 80);
            AddColumn(gvTeaching, gbBand, "TeacherFirstName", "Họ đệm", 120);
            AddColumn(gvTeaching, gbBand, "TeacherLastName", "Tên", 100);
            AddColumn(gvTeaching, gbBand, "ClassID", "Mã lớp", 100);
            AddColumn(gvTeaching, gbBand, "SubjectID", "Mã HP/ Mã công tác", 110);
            AddColumn(gvTeaching, gbBand, "SubjectName", "Tên môn", 200, "", DevExpress.Utils.HorzAlignment.Near);
            AddColumn(gvTeaching, gbBand, "ClassSize", "Sĩ số", 70, "#,##0");
            AddColumn(gvTeaching, gbBand, "Semester", "HK", 50);
            AddColumn(gvTeaching, gbBand, "TotalQuantity_Theory", "LT", 80, "#,##0.00");
            AddColumn(gvTeaching, gbBand, "TotalQuantity_Practice", "TH", 80, "#,##0.00");
            AddColumn(gvTeaching, gbBand, "TongLTTH", "Tổng LT+TH", 90, "#,##0.00");
            AddColumn(gvTeaching, gbBand, "HeSo", "Hệ số", 70, "#,##0.00");
            AddColumn(gvTeaching, gbBand, "QuyDoiGio", "Quy đổi giờ", 100, "#,##0.00");

            HighlightColumn(gvTeaching, "TongLTTH", Color.FromArgb(255, 255, 192));
            HighlightColumn(gvTeaching, "QuyDoiGio", Color.LightSkyBlue);

            gvTeaching.SummaryCollection =
                "TotalQuantity_Theory,TotalQuantity_Practice,TongLTTH,QuyDoiGio";
        }

        private void InitGridTeacherWork(Control.DgAdvBandedGridView gv, string bandCaption)
        {
            gv.Bands.Clear();
            gv.Columns.Clear();
            gv.OptionsBehavior.Editable = false;

            GridBand gbBand = CreateBand(gv, bandCaption);

            AddColumn(gv, gbBand, "TeacherID", "Mã giáo viên", 90);
            AddColumn(gv, gbBand, "TeacherFirstName", "Họ đệm", 120);
            AddColumn(gv, gbBand, "TeacherLastName", "Tên", 100);
            AddColumn(gv, gbBand, "TeacherWorkName", "Tên công việc", 180, "", DevExpress.Utils.HorzAlignment.Near);
            AddColumn(gv, gbBand, "Ratio", "Hệ số", 70, "#,##0.00");
            AddColumn(gv, gbBand, "RequestQuantity", "Buổi", 70, "#,##0.00");
            AddColumn(gv, gbBand, "RequestTotal", "Số giờ", 80, "#,##0.00");
            AddColumn(gv, gbBand, "StandardHour", "Số giờ chuẩn", 100, "#,##0.00");
            AddColumn(gv, gbBand, "Description", "Nội dung", 220, "", DevExpress.Utils.HorzAlignment.Near);

            HighlightColumn(gv, "RequestQuantity", Color.FromArgb(255, 255, 192));
            HighlightColumn(gv, "RequestTotal", Color.FromArgb(192, 255, 192));
            HighlightColumn(gv, "StandardHour", Color.LightSkyBlue);

            gv.SummaryCollection = "RequestQuantity,RequestTotal,StandardHour";
        }

        private void InitGridResearch()
        {
            gvResearch.Bands.Clear();
            gvResearch.Columns.Clear();
            gvResearch.OptionsBehavior.Editable = false;

            GridBand gbBand = CreateBand(gvResearch, "Nhóm Nghiên cứu khoa học");

            AddColumn(gvResearch, gbBand, "TeacherID", "Mã giáo viên", 90);
            AddColumn(gvResearch, gbBand, "TeacherFirstName", "Họ đệm", 120);
            AddColumn(gvResearch, gbBand, "TeacherLastName", "Tên", 100);
            AddColumn(gvResearch, gbBand, "SavePrev", "Giờ NCKH bảo lưu năm trước", 140, "#,##0.00");
            AddColumn(gvResearch, gbBand, "ResearchNow", "Số giờ NCKH năm nay", 130, "#,##0.00");
            AddColumn(gvResearch, gbBand, "ResearchContent", "Nội dung nghiên cứu", 250, "", DevExpress.Utils.HorzAlignment.Near);

            HighlightColumn(gvResearch, "ResearchNow", Color.LightSkyBlue);

            gvResearch.SummaryCollection = "SavePrev,ResearchNow";
        }

        private GridBand CreateBand(Control.DgAdvBandedGridView gv, string caption)
        {
            GridBand band = new GridBand();
            band.Caption = caption;
            band.AppearanceHeader.Font = new Font("Tahoma", 9, FontStyle.Bold);
            band.AppearanceHeader.Options.UseFont = true;
            band.AppearanceHeader.TextOptions.HAlignment = DevExpress.Utils.HorzAlignment.Center;
            band.AppearanceHeader.Options.UseTextOptions = true;
            gv.Bands.Add(band);
            gv.BandPanelRowHeight = 28;
            return band;
        }

        private void HighlightColumn(Control.DgAdvBandedGridView gv, string fieldName, Color backColor)
        {
            BandedGridColumn col = gv.Columns[fieldName] as BandedGridColumn;
            if (col == null)
                return;

            col.AppearanceCell.BackColor = backColor;
            col.AppearanceCell.Options.UseBackColor = true;
            col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
            col.AppearanceCell.Options.UseFont = true;
        }

        private void AddColumn(
            Control.DgAdvBandedGridView gv,
            GridBand band,
            string fieldName,
            string caption,
            int width,
            string format,
            DevExpress.Utils.HorzAlignment cellAlign)
        {
            BandedGridColumn col = new BandedGridColumn();

            col.FieldName = fieldName;
            col.Caption = caption;
            col.Name = gv.Name + "_gcol" + fieldName;
            col.Visible = true;
            col.Width = width;
            col.OptionsColumn.AllowEdit = false;

            col.AppearanceHeader.Options.UseTextOptions = true;
            col.AppearanceHeader.TextOptions.HAlignment =
                DevExpress.Utils.HorzAlignment.Center;

            col.AppearanceCell.Options.UseTextOptions = true;
            col.AppearanceCell.TextOptions.HAlignment = cellAlign;

            if (!string.IsNullOrEmpty(format))
            {
                col.DisplayFormat.FormatString = format;
                col.DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            }

            gv.Columns.Add(col);
            band.Columns.Add(col);
        }

        private void AddColumn(
            Control.DgAdvBandedGridView gv,
            GridBand band,
            string fieldName,
            string caption,
            int width,
            string format)
        {
            AddColumn(gv, band, fieldName, caption, width, format, DevExpress.Utils.HorzAlignment.Center);
        }

        private void AddColumn(
            Control.DgAdvBandedGridView gv,
            GridBand band,
            string fieldName,
            string caption,
            int width)
        {
            AddColumn(gv, band, fieldName, caption, width, "", DevExpress.Utils.HorzAlignment.Center);
        }

        #endregion

        private static decimal ToDecimal(object value)
        {
            if (value == null || value == DBNull.Value)
                return 0;

            return Convert.ToDecimal(value);
        }

        private static object GetColumnValue(DataRow row, string columnName)
        {
            if (row == null || row.Table == null)
                return null;

            if (!row.Table.Columns.Contains(columnName))
                return null;

            return row[columnName];
        }

        private static string GetString(DataRow row, string columnName)
        {
            object value = GetColumnValue(row, columnName);
            if (value == null || value == DBNull.Value)
                return "";

            return value.ToString().Trim();
        }

        private void BeginProcess()
        {
            btnSearch.Enabled = btnClose.Enabled = false;
        }

        private void EndProcess()
        {
            btnSearch.Enabled = btnClose.Enabled = true;
        }

        private bool IsValidData()
        {
            if (uYearSemester.YearIDEditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn niên học!");
                uYearSemester.Focus();
                return false;
            }

            return true;
        }

        #endregion

        #region Form Actions

        private void frmBangTongHopGioChiTietGiangVien_Load(object sender, EventArgs e)
        {
            CheckPermission();
            SetToolTip();
            InitAllGridsEmpty();
            new Thread(LoadReferenceData).Start();
        }

        private void frmBangTongHopGioChiTietGiangVien_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F3:
                    btnSearch_Click(sender, null);
                    break;

                case Keys.F5:
                    mnuItemRefresh_Click(sender, null);
                    break;
            }
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (!IsValidData())
                return;

            BeginProcess();
            new Thread(LoadData).Start();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            Close();
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            RefreshReferenceData();
            btnSearch_Click(sender, e);
        }

        private void btnPrint_Click(object sender, EventArgs e)
        {
            if (!HasRows(dtbTeaching)
                && !HasRows(dtbWork35)
                && !HasRows(dtbWork34)
                && !HasRows(dtbResearch))
            {
                MessageManager.Warning("Không có dữ liệu để in!");
                return;
            }

            gcTeaching.ShowPrintPreview();
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            if (HasRows(dtbTeaching))
                gvTeaching.QuickExportToExcel();
            else if (HasRows(dtbWork35))
                gvWork35.QuickExportToExcel();
            else if (HasRows(dtbWork34))
                gvWork34.QuickExportToExcel();
            else if (HasRows(dtbResearch))
                gvResearch.QuickExportToExcel();
            else
                MessageManager.Warning("Không có dữ liệu để xuất!");
        }

        private void uSubjectGroup_EditValueChanged(object sender, EventArgs e)
        {
            string strCondition = "";

            if (uSubjectGroup.ScienceEditValue != null)
            {
                strCondition =
                    "ScienceID = '" +
                    uSubjectGroup.ScienceEditValue.ToString() +
                    "'";
            }

            if (uSubjectGroup.SubjectGroupEditValue != null)
            {
                strCondition +=
                    (strCondition == "" ? "" : " And ")
                    + " SubjectGroupID = '"
                    + uSubjectGroup.SubjectGroupEditValue.ToString()
                    + "'";
            }

            SIM_TeacherService.InitGridLookUpEdit(
                lookupTeacherID,
                strCondition
            );
        }

        private void chkFullYear_CheckedChanged(object sender, EventArgs e)
        {
            uYearSemester.SemesterEdit.Enabled = !chkFullYear.Checked;
            if (chkFullYear.Checked)
                uYearSemester.SemesterEditValue = null;
        }

        #endregion
    }
}

namespace ScheduleManager.Teaching
{
    partial class frmBangTongHopGioChiTietGiangVien
    {
