        grpTeaching.Height
        + grpWork35.Height
        + grpWork34.Height
        + grpResearch.Height
        + 30;

    pnlContent.AutoScrollMinSize = new Size(0, intTotalHeight);
    pnlContent.AutoScrollPosition = new Point(0, 0);
}

private void FitSectionHeight(
    GroupBox grp,
    Control.DgAdvBandedGridView gv,
    DataTable dtb)
{
    int intRowCount = 0;
    if (dtb != null)
        intRowCount = dtb.Rows.Count;

    // Không hiện scrollbar trong lưới — cuộn ở panel ngoài
    gv.VertScrollVisibility = DevExpress.XtraGrid.Views.Base.ScrollVisibility.Never;

    int intBandHeight = gv.BandPanelRowHeight;
    if (intBandHeight <= 0)
        intBandHeight = 28;

    int intColumnHeight = gv.ColumnPanelRowHeight;
    if (intColumnHeight <= 0)
        intColumnHeight = 24;

    int intRowHeight = gv.RowHeight;
    if (intRowHeight <= 0)
        intRowHeight = 22;

    int intFooterHeight = 0;
    if (gv.OptionsView.ShowFooter)
        intFooterHeight = 24;

    // Ít nhất 1 dòng trống để thấy header
    int intVisibleRows = intRowCount;
    if (intVisibleRows < 1)
        intVisibleRows = 1;

    int intGroupChrome = 32;
    int intPadding = 10;
    int intContentHeight =
        intBandHeight
        + intColumnHeight
        + (intVisibleRows * intRowHeight)
        + intFooterHeight
        + intPadding;

    grp.Height = intGroupChrome + intContentHeight;
}

