        #region HTML Export

        private void ExportToHTML()
        {
            if (!IsTeacherSelected())
            {
                MessageManager.Warning("Bạn phải chọn giảng viên để in HTML!");
                lookupTeacherID.Focus();
                return;
            }

            if (!HasRows(dtbTeaching)
                && !HasRows(dtbWork35)
                && !HasRows(dtbWork34)
                && !HasRows(dtbResearch))
            {
                MessageManager.Warning("Không có dữ liệu để xuất!");
                return;
            }

            string strTeacherID = GetSelectedTeacherID();
            string strFilePath = ExportTeacherHTML(strTeacherID);

            if (strFilePath == "")
            {
                MessageManager.Warning("Không có dữ liệu của giảng viên đã chọn để xuất!");
                return;
            }

            System.Diagnostics.Process.Start(strFilePath);
        }

        private string ExportTeacherHTML(string strTeacherID)
        {
            DataTable dtbTeachingFilter = FilterByTeacher(dtbTeaching, strTeacherID);
            DataTable dtbWork35Filter = FilterByTeacher(dtbWork35, strTeacherID);
            DataTable dtbWork34Filter = FilterByTeacher(dtbWork34, strTeacherID);
            DataTable dtbResearchFilter = FilterByTeacher(dtbResearch, strTeacherID);

            if (!HasRows(dtbTeachingFilter)
                && !HasRows(dtbWork35Filter)
                && !HasRows(dtbWork34Filter)
                && !HasRows(dtbResearchFilter))
            {
                return "";
            }

            DataRow drwFirst = GetFirstTeacherRow(
                dtbTeachingFilter,
                dtbWork35Filter,
                dtbWork34Filter,
                dtbResearchFilter);

            if (drwFirst == null)
                return "";

            decimal decTongQuyDoi = 0;
            decimal decTongWork35 = 0;
            decimal decTongWork34 = 0;
            decimal decTongNCKH = 0;
            decimal decSavePrev = 0;

            string strDetailGiangDay = BuildTeachingDetailHtml(dtbTeachingFilter, out decTongQuyDoi);
            string strDetailWork35 = BuildTeacherWorkDetailHtml(dtbWork35Filter, out decTongWork35);
            string strDetailWork34 = BuildTeacherWorkDetailHtml(dtbWork34Filter, out decTongWork34);
            string strDetailNCKH = BuildResearchDetailHtml(
                dtbResearchFilter,
                out decTongNCKH,
                out decSavePrev);

            string strFileName = "BangTongHopGioChiTietGiangVien.htm";
            string strFileContent = ReadHtmlTemplate(strFileName);
            if (string.IsNullOrEmpty(strFileContent))
                return "";

            strFileContent = strFileContent.Replace("{HEADER_LEFT}", BuildHeaderLeft());
            strFileContent = strFileContent.Replace("{HEADER_RIGHT}", BuildHeaderRight());
            strFileContent = strFileContent.Replace("{YEAR}", GetYearText());
            strFileContent = strFileContent.Replace("{DOT_LINE}", GetDotLineHtml());
            strFileContent = strFileContent.Replace("{TEACHER_INFO}", BuildTeacherInfo(drwFirst));
            strFileContent = strFileContent.Replace("{DONVI}", HtmlEncode(GetTeacherDonVi(drwFirst)));
            strFileContent = strFileContent.Replace("{DETAIL_GIANG_DAY}", strDetailGiangDay);
            strFileContent = strFileContent.Replace("{DETAIL_HOAT_DONG_KHAC}", strDetailWork35);
            strFileContent = strFileContent.Replace("{DETAIL_BOI_DUONG}", strDetailWork34);
            strFileContent = strFileContent.Replace("{DETAIL_NCKH}", strDetailNCKH);

            strFileContent = strFileContent.Replace("{TONG_GIO_QUY_DOI}", FormatNumber(decTongQuyDoi, 2));
            strFileContent = strFileContent.Replace("{TONG_GIO_HDCD}", FormatNumber(decTongWork35, 2));
            strFileContent = strFileContent.Replace("{TONG_GIO_HTBD}", FormatNumber(decTongWork34, 2));
            strFileContent = strFileContent.Replace("{TONG_GIO_NCKH}", FormatNumber(decTongNCKH, 2));
            strFileContent = strFileContent.Replace("{GIO_BAO_LUU_NCKH_TRUOC}", FormatNumber(decSavePrev, 2));

            strFileContent = strFileContent.Replace("{PLACE_DATE}", BuildPlaceDate());
            strFileContent = strFileContent.Replace("{TEACHER_NAME_SIGN}", HtmlEncode(GetTeacherFullName(drwFirst)));

            string strFileNameAs = String.Format(
                "{0}_{1}_{2}",
                strTeacherID,
                DateTime.Now.ToString("yyyyMMdd_HHmmss"),
                strFileName);

            return WriteHtmlFile(strFileNameAs, strFileContent);
        }

        private static DataTable FilterByTeacher(DataTable dtbSource, string strTeacherID)
        {
            if (dtbSource == null)
                return null;

            DataTable dtbResult = dtbSource.Clone();
            if (!dtbSource.Columns.Contains("TeacherID"))
                return dtbResult;

            foreach (DataRow row in dtbSource.Rows)
            {
                string strRowTeacherID = GetColumnText(row, "TeacherID");
                if (strRowTeacherID == strTeacherID)
                    dtbResult.ImportRow(row);
            }

            return dtbResult;
        }

        private static DataRow GetFirstTeacherRow(
            DataTable dtb1,
            DataTable dtb2,
            DataTable dtb3,
            DataTable dtb4)
        {
            if (HasRows(dtb1))
                return dtb1.Rows[0];
            if (HasRows(dtb2))
                return dtb2.Rows[0];
            if (HasRows(dtb3))
                return dtb3.Rows[0];
            if (HasRows(dtb4))
                return dtb4.Rows[0];

            return null;
        }

