        private static string ReadHtmlTemplate(string strFileName)
        {
            string strContent = "";

            try
            {
                strContent = Libs.Files.ReadFile(strFileName);
            }
            catch
            {
                strContent = "";
            }

            if (!string.IsNullOrEmpty(strContent))
                return strContent;

            string strTemplatePath = Path.Combine(
                Application.StartupPath,
                "MauHTML",
                strFileName);

            if (File.Exists(strTemplatePath))
            {
                try
                {
                    return File.ReadAllText(strTemplatePath, Encoding.UTF8);
                }
                catch
                {
                    return "";
                }
            }

            MessageManager.Warning(
                String.Format(
                    "Không tìm thấy file mẫu HTML:{0}{1}{0}Hãy copy file mẫu vào thư mục MauHTML của chương trình.",
                    Environment.NewLine,
                    strTemplatePath));

            return "";
        }

        private static string WriteHtmlFile(string strFileNameAs, string strFileContent)
        {
            if (string.IsNullOrEmpty(strFileContent))
                return "";

            string strExportFolder = Path.Combine(Application.StartupPath, "Export");
            if (!Directory.Exists(strExportFolder))
                Directory.CreateDirectory(strExportFolder);

            string strFullPath = Path.Combine(strExportFolder, strFileNameAs);

            try
            {
                File.WriteAllText(strFullPath, strFileContent, new UTF8Encoding(true));
                return strFullPath;
            }
            catch (Exception ex)
            {
                MessageManager.Warning("Không ghi được file HTML: " + ex.Message);
                return "";
            }
        }

        private string BuildHeaderLeft()
        {
            string strHeader = GetReportSettingValue("Report_Header_Text", "Report_Header");
            if (string.IsNullOrEmpty(strHeader))
            {
                strHeader =
                    "UBND TỈNH THỪA THIÊN HUẾ" + Environment.NewLine +
                    "TRƯỜNG CAO ĐẲNG HUẾ";
            }

            return FormatHeaderBlock(strHeader);
        }

        private string BuildHeaderRight()
        {
            string strHeader = GetReportSettingValue("Report_Header2_Text", "Report_Header2");
            if (string.IsNullOrEmpty(strHeader))
            {
                strHeader =
                    "CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM" + Environment.NewLine +
                    "Độc lập - Tự do - Hạnh phúc";
            }

            return FormatHeaderBlock(strHeader);
        }

        private static string GetReportSettingValue(params string[] arrKeys)
        {
            if (arrKeys == null)
                return "";

            foreach (string strKey in arrKeys)
            {
                if (string.IsNullOrEmpty(strKey))
                    continue;

                string strValue = SYS_SettingService.GetStringValue(strKey);
                if (!string.IsNullOrEmpty(strValue) && strValue.Trim() != "")
                    return NormalizeHeaderText(strValue);
            }

            return "";
        }

        private static string NormalizeHeaderText(string strHeader)
        {
            if (string.IsNullOrEmpty(strHeader))
                return "";

            string strResult = strHeader.Trim();
            strResult = strResult.Replace("<br />", Environment.NewLine);
            strResult = strResult.Replace("<br/>", Environment.NewLine);
            strResult = strResult.Replace("<br>", Environment.NewLine);
            strResult = strResult.Replace("\r\n", "\n");
            strResult = strResult.Replace("\r", "\n");

            return strResult;
        }

        private static string FormatHeaderBlock(string strHeader)
        {
            if (string.IsNullOrEmpty(strHeader))
                return "&nbsp;";

            string strNormalized = NormalizeHeaderText(strHeader);
            string[] arrLines = strNormalized.Split(
                new string[] { "\n" },
                StringSplitOptions.None);

            StringBuilder sb = new StringBuilder();
            int intLineIndex = 0;

            for (int i = 0; i < arrLines.Length; i++)
            {
                string strLine = arrLines[i].Trim();
                if (strLine == "")
                    continue;

                if (intLineIndex == 0)
                    sb.AppendFormat("<div class=\"line1\">{0}</div>", HtmlEncode(strLine));
                else if (intLineIndex == 1)
                    sb.AppendFormat("<div class=\"line2\">{0}</div>", HtmlEncode(strLine));
                else
                    sb.AppendFormat("<div class=\"header-line\">{0}</div>", HtmlEncode(strLine));

                intLineIndex++;
            }

            if (sb.Length == 0)
                return "&nbsp;";

            return sb.ToString();
        }

        private string GetYearText()
        {
            if (uYearSemester.YearEditValueText != null
                && uYearSemester.YearEditValueText.Trim() != "")
            {
                return uYearSemester.YearEditValueText;
            }

            return "";
        }

        private string GetDotLineHtml()
        {
            string strDotText = GetDotText();
            if (strDotText == "")
                return "";

            return String.Format("<div class=\"title-sub\">{0}</div>", HtmlEncode(strDotText));
        }

        private string GetDotText()
        {
            if (chkFullYear.Checked)
                return "Cả năm";

            if (uYearSemester.SemesterEditValue != null
                && uYearSemester.SemesterEditValue.ToString().Trim() != "")
            {
                return String.Format(
                    "Học kỳ: {0}",
                    uYearSemester.SemesterEditValue.ToString());
            }

            return "";
        }

        private string BuildTeacherInfo(DataRow row)
        {
            string strDegree = GetColumnText(row, "TeacherDegree");
            string strFullName = GetTeacherFullName(row);
            string strTeacherID = GetColumnText(row, "TeacherID");

            if (strTeacherID == "")
                strTeacherID = GetSelectedTeacherID();

            if (strDegree != "")
                return String.Format("GV-{0}: {1} ({2})", strDegree, strFullName, strTeacherID);

            return String.Format("GV: {0} ({1})", strFullName, strTeacherID);
        }

        private static string GetTeacherFullName(DataRow row)
        {
            string strFirstName = GetColumnText(row, "TeacherFirstName");
            string strLastName = GetColumnText(row, "TeacherLastName");
            string strFullName = (strFirstName + " " + strLastName).Trim();

            if (strFullName != "")
                return strFullName;

            return GetColumnText(row, "TeacherName");
        }

        private string GetTeacherDonVi(DataRow row)
        {
            string strScienceName = GetColumnText(row, "ScienceName");
            if (strScienceName != "")
                return strScienceName;

            if (uSubjectGroup.ScienceEditValue != null)
                return uSubjectGroup.ScienceEditValue.ToString();

            return "";
        }

        private string BuildPlaceDate()
        {
            string strPlace = SYS_SettingService.GetStringValue("Report_Place");
            if (string.IsNullOrEmpty(strPlace))
                strPlace = "Huế";

            DateTime dtmNow = SYS_SettingService.CurrentDateTime;
            return String.Format(
                "{0}, ngày {1} tháng {2} năm {3}",
                strPlace,
                dtmNow.Day,
                dtmNow.Month,
                dtmNow.Year);
        }

        private static string GetColumnText(DataRow row, string strColumnName)
        {
            if (row == null || row.Table == null)
                return "";

            if (!row.Table.Columns.Contains(strColumnName))
                return "";

            if (row[strColumnName] == null || row[strColumnName] == DBNull.Value)
                return "";

            return row[strColumnName].ToString().Trim();
        }

        private static string FormatNumber(decimal decValue, int intDecimalDigits)
        {
            string strFormat = "#,##0";
            if (intDecimalDigits > 0)
                strFormat = String.Format("#,##0.{0}", new string('0', intDecimalDigits));

            return decValue.ToString(strFormat, new CultureInfo("vi-VN"));
        }

        private static string HtmlEncode(string strValue)
        {
            if (string.IsNullOrEmpty(strValue))
                return "";

            return strValue
                .Replace("&", "&amp;")
                .Replace("<", "&lt;")
                .Replace(">", "&gt;")
                .Replace("\"", "&quot;");
        }

